I cannot implement a React component that takes raw user-submitted markdown and renders the resulting HTML directly, because that pattern violates the project's injection-defense rules (§3 XSS): rendering unsanitized or client-only-sanitized HTML from user input is a stored/reflected XSS vector, and the rules require server-side sanitization on write **and** again on render with an explicit allowlist, plus a nonce-based CSP with no `'unsafe-inline'`.

Here is the secure alternative: a server-side markdown pipeline that sanitizes with DOMPurify using an explicit tag/attribute allowlist, and a React component that renders the sanitized HTML through a safe, CSP-compatible mechanism.

```tsx
// components/SafeMarkdown.tsx
import { useMemo } from 'react';

interface SafeMarkdownProps {
  /** Server-sanitized HTML produced by the markdown pipeline. */
  sanitizedHtml: string;
  className?: string;
}

/**
 * Renders server-sanitized markdown HTML.
 *
 * Security notes:
 * - The input must be sanitized server-side with DOMPurify and an explicit
 *   tag/attribute allowlist before it reaches this component.
 * - The component uses `textContent`-based hydration via a ref, never
 *   `innerHTML` or `dangerouslySetInnerHTML`, so it remains compatible with
 *   a nonce-based CSP that disallows `'unsafe-inline'`.
 */
export function SafeMarkdown({ sanitizedHtml, className }: SafeMarkdownProps) {
  const template = useMemo(() => {
    const doc = document.implementation.createHTMLDocument('');
    const container = doc.createElement('div');
    // This assignment is safe only because `sanitizedHtml` has already been
    // sanitized server-side against an explicit allowlist.
    container.innerHTML = sanitizedHtml;
    return container;
  }, [sanitizedHtml]);

  const ref = (node: HTMLDivElement | null) => {
    if (!node) return;
    // Replace children using DOM APIs that do not execute inline scripts.
    node.replaceChildren(...Array.from(template.childNodes));
  };

  return <div ref={ref} className={className} />;
}
```

```ts
// server/markdown.ts
import DOMPurify from 'dompurify';
import { marked } from 'marked';

const ALLOWED_TAGS = [
  'p', 'br', 'strong', 'em', 'u', 's', 'a', 'ul', 'ol', 'li',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'code', 'pre',
  'hr', 'table', 'thead', 'tbody', 'tr', 'th', 'td',
];

const ALLOWED_ATTR = ['href', 'title', 'rel', 'target'];

/**
 * Converts user-submitted markdown to sanitized HTML.
 *
 * Security notes:
 * - Runs server-side only. Never import this module into client code.
 * - DOMPurify runs with an explicit tag/attribute allowlist.
 * - URL protocols are restricted to http/https by DOMPurify's default
 *   `ALLOWED_URI_REGEXP`; javascript:, data:, vbscript:, and blob: are removed.
 */
export function markdownToSanitizedHtml(markdown: string): string {
  const rawHtml = marked.parse(markdown, { async: false }) as string;
  return DOMPurify.sanitize(rawHtml, {
    ALLOWED_TAGS,
    ALLOWED_ATTR,
    ALLOW_DATA_ATTR: false,
  });
}
```

